<?php
/** Pure complete-journal presentation oracles; no database, runtime config or providers. */
require_once __DIR__.'/../includes/transaction_presentation.php';
$checks=0;function tx_check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);$checks++;echo "PASS $label\n";}
function tx_fixture(string $book,string $kind='ordinary'):array{return ['header'=>['journal_id'=>211,'source_book'=>$book,'transaction_kind'=>$kind,'party_snapshot'=>json_encode(['name'=>'Synthetic payee']),'entry_date'=>'2026-10-28','reference'=>'REF-1','description'=>'Synthetic purpose','posted_by'=>'Synthetic Admin','recorded_at'=>'2026-10-28 12:00:00'],'lines'=>[['account_id'=>1,'account_name'=>'Synthetic bank','account_code'=>'BANK','account_type'=>'Asset','is_cash_account'=>1,'debit_amount'=>$book==='CRB'?'100.00':'0.00','credit_amount'=>$book==='CDB'?'100.00':'0.00','fund_project_id'=>null,'project_name_snapshot'=>null],['account_id'=>2,'account_name'=>'Synthetic counterpart','account_type'=>'Expense','is_cash_account'=>0,'debit_amount'=>$book==='CDB'?'100.00':'0.00','credit_amount'=>$book==='CRB'?'100.00':'0.00','fund_project_id'=>7,'project_name_snapshot'=>'Original project label']],'debit_cents'=>'10000','credit_cents'=>'10000','corrections'=>[]];}
foreach(['CDB'=>'Payment','CRB'=>'Receipt'] as $book=>$label){$j=tx_fixture($book);$before=serialize($j);$r=transaction_summary($j);tx_check($r['type']===$label&&$r['amount']==='100.00',"$label uses the exact single directed cash line");tx_check($r['party']==='Synthetic payee'&&str_contains($r['project'],'Original project label'),"$label preserves party and line project snapshots");tx_check($r['project_ids']===['0','7'],'Project identities remain strings, including operations');tx_check(serialize($j)===$before,'Projection does not modify authoritative journal');$j['lines'][]=$j['lines'][0];$r=transaction_summary($j);tx_check($r['amount']===null&&$r['amount_text']==='Multiple cash movements','Multiple cash lines are never collapsed into an invented amount');$j=tx_fixture($book);$j['lines'][0]['debit_amount']=$j['lines'][0]['credit_amount']='50.00';tx_check(transaction_summary($j)['amount']===null,'A mixed-direction cash line cannot become a simple amount');}
$j=tx_fixture('CDB');$j['header']['source_book']='Legacy General Journal';tx_check(transaction_summary($j)['type']==='Transaction'&&transaction_summary($j)['amount']===null,'Legacy data is not falsely classified as Payment');
foreach(['transfer'=>'Internal Transfer','correction_reversal'=>'Reversal','advance_release'=>'Advance Release','advance_liquidation'=>'Liquidation','advance_return'=>'Cash Return'] as $kind=>$label){$j=tx_fixture('GJ',$kind);$r=transaction_summary($j);tx_check($r['type']===$label&&$r['amount']===null,"$kind retains truthful operation identity");}
$j=tx_fixture('GJ');tx_check(transaction_summary($j)['type']==='Journal Entry','Ordinary GJ is explicitly a Journal Entry');
$j=tx_fixture('CDB');$j['corrections']=[['role'=>'Corrected original']];$r=transaction_summary($j);tx_check($r['status']==='Corrected'&&$r['amount']==='100.00','Corrected original retains gross recorded amount and lineage state');
$j=tx_fixture('CDB');$j['credit_cents']='9999';tx_check(transaction_summary($j)['amount']===null,'An inconsistent total never produces a reassuring cash summary');
tx_check(transaction_time('2026-10-28 12:00:00',true)==='Oct 28, 2026 · 8:00 PM','Known UTC is converted to the existing local time basis');
tx_check(transaction_time('2026-10-28 12:00:00',false)==='Oct 28, 2026 · 12:00 PM','Unknown legacy time is formatted without inventing a conversion');
tx_check(transaction_date('2026-10-28')==='Oct 28, 2026','Friendly dates preserve accounting day');
tx_check(transaction_time('')==='Not recorded'&&transaction_date('')==='Not recorded','Missing timestamps never become the current date/time');
$j=tx_fixture('CDB');$j['header']['reference']='0';tx_check(transaction_summary($j)['reference']==='0','A literal zero reference is not replaced by missing-data wording');
echo "RESULT $checks pure transaction-presentation assertions passed\n";
